CREATE TRIGGER protect_billing_agreements_owner BEFORE UPDATE ON billing_agreements FOR EACH ROW BEGIN IF NOT (NEW.id<=>OLD.id) OR NOT (NEW.created_at<=>OLD.created_at) OR NOT (NEW.tenant_kind<=>OLD.tenant_kind) OR NOT (NEW.tenant_id<=>OLD.tenant_id) OR NOT (NEW.plan_id<=>OLD.plan_id) OR NOT (NEW.request_key<=>OLD.request_key) OR (OLD.checkout_url IS NOT NULL AND NOT (BINARY NEW.checkout_url<=>BINARY OLD.checkout_url)) OR (OLD.provider_id IS NOT NULL AND NOT (BINARY NEW.provider_id<=>BINARY OLD.provider_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable billing ownership'; END IF; END
